/* Banco documental de Databricks 2026: 92 preguntas originales, independientes del banco histórico. */
const DOCUMENTAL_2026_RAW=[{"id":"DOC26-P01","area":"P","section":"Databricks Intelligence Platform","topic":"Selección de cómputo","level":3,"question":"A reporting team runs ad-hoc SQL dashboards over Delta tables. Low cold-start latency and managed scaling are more important than custom Spark JVM settings. Which compute should they choose?","options":["A serverless SQL warehouse","A classic all-purpose cluster","A job cluster for each dashboard viewer","A dedicated Spark Submit cluster"],"correct":0,"why":"Un SQL warehouse serverless está optimizado para BI y consultas SQL, con arranque y escalado gestionados.","whyWrong":"Los clusters de jobs y Spark Submit son para procesamiento; el all-purpose no es el recomendado para servir BI.","doc":"https://docs.databricks.com/aws/en/compute/choose-compute","sourceKey":"compute","code":""},{"id":"DOC26-P02","area":"P","section":"Databricks Intelligence Platform","topic":"Selección de cómputo","level":3,"question":"A notebook-based batch job requires an unsupported native library and JVM customization unavailable on serverless. What is the most appropriate compute?","options":["Classic jobs compute with the required configuration","Serverless jobs, which always allow JVM customization","Serverless SQL warehouse for running Scala JARs","All-purpose compute for production because it has lower total cost"],"correct":0,"why":"Classic jobs compute permite ajustar configuraciones no disponibles en serverless.","whyWrong":"Serverless no cubre todos los requisitos de personalización; all-purpose suele desaconsejarse para producción automatizada.","doc":"https://docs.databricks.com/aws/en/jobs/compute","sourceKey":"jobscompute","code":""},{"id":"DOC26-P03","area":"P","section":"Databricks Intelligence Platform","topic":"Tipos de cómputo","level":3,"question":"A Lakeflow Job includes SQL query tasks and notebook tasks. Which compute pairing aligns with Databricks recommendations?","options":["SQL queries on a job cluster; notebooks on a classic SQL warehouse","SQL queries on a SQL warehouse; notebooks on serverless jobs compute when supported","SQL queries on serverless pipelines; notebooks on a SQL editor session","Both task types must share the same all-purpose cluster"],"correct":1,"why":"SQL tasks usan SQL warehouse; notebooks pueden usar serverless jobs cuando son compatibles.","whyWrong":"Las otras opciones intercambian tipos de cómputo que responden a cargas diferentes.","doc":"https://docs.databricks.com/aws/en/jobs/compute","sourceKey":"jobscompute","code":""},{"id":"DOC26-P04","area":"P","section":"Databricks Intelligence Platform","topic":"Componentes de plataforma","level":3,"question":"Two workspaces require the same governed tables, permissions, and lineage. Which platform component provides centralized table metadata and access control?","options":["Photon","Delta Cache","Repos","Unity Catalog"],"correct":3,"why":"Unity Catalog centraliza metadatos, permisos, linaje y gobierno de activos.","whyWrong":"Repos gestiona código, Photon es motor de consultas y la caché no es un catálogo de gobierno.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/","sourceKey":"detail","code":""},{"id":"DOC26-P05","area":"P","section":"Databricks Intelligence Platform","topic":"Almacenamiento","level":3,"question":"An engineer must explain why Delta tables can support atomic updates and historical version queries over cloud object storage. What is the essential mechanism?","options":["A transaction log tracks table versions and commits","An external OLTP database serializes every SELECT","Each SQL warehouse maintains its own copy of every row","Only CSV files are used"],"correct":0,"why":"Delta Lake usa un registro transaccional para mantener versiones consistentes y commits ACID.","whyWrong":"La garantía no proviene de CSV, de SQL warehouses individuales ni de una base OLTP obligatoria.","doc":"https://docs.databricks.com/aws/en/delta/","sourceKey":"detail","code":""},{"id":"DOC26-P06","area":"P","section":"Databricks Intelligence Platform","topic":"Motor de ejecución","level":3,"question":"A team wants to accelerate compatible SQL/DataFrame workloads without rewriting Spark transformation code. Which Databricks engine is designed for that?","options":["Unity Catalog volumes","Auto Loader","Lakehouse Federation","Photon"],"correct":3,"why":"Photon es el motor vectorizado de ejecución optimizada para consultas y operaciones compatibles.","whyWrong":"Federation conecta fuentes, Auto Loader ingiere archivos y los volumes almacenan archivos.","doc":"https://docs.databricks.com/aws/en/optimizations","sourceKey":"opt","code":""},{"id":"DOC26-I01","area":"I","section":"Data Ingestion and Loading","topic":"COPY INTO · opciones","level":3,"question":"A Delta target must load Parquet files with different source schemas and also add newly discovered columns to the target table. Which configuration covers both requirements?","options":["FORMAT_OPTIONS ('inferSchema'='true') only","COPY_OPTIONS ('mergeSchema'='true') only","FORMAT_OPTIONS ('mergeSchema'='true') and COPY_OPTIONS ('mergeSchema'='true')","FORMAT_OPTIONS ('mergeSchema'='true') only"],"correct":2,"why":"El mergeSchema del lector combina esquemas de Parquet; el del comando permite evolución del destino Delta.","whyWrong":"Activar solo uno de los dos resuelve una parte del problema; inferSchema no sustituye ambas funciones.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into","sourceKey":"copy","code":"COPY INTO main.bronze.events\nFROM '/Volumes/main/raw/landing/events'\nFILEFORMAT = PARQUET\n-- choose the options"},{"id":"DOC26-I02","area":"I","section":"Data Ingestion and Loading","topic":"COPY INTO · FORCE","level":3,"question":"A JSON file was loaded yesterday with COPY INTO and then overwritten at the same path. The team explicitly wants to reprocess it, accepting possible duplicates. Which option disables file skipping?","options":["FORMAT_OPTIONS ('force'='true')","VALIDATE ALL","COPY_OPTIONS ('force'='true')","COPY_OPTIONS ('mergeSchema'='true')"],"correct":2,"why":"COPY_OPTIONS force=true vuelve a cargar archivos ya registrados en el historial de COPY INTO.","whyWrong":"mergeSchema se refiere a estructura; VALIDATE no ingiere; force no es una opción del lector FORMAT_OPTIONS.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into","sourceKey":"copy","code":""},{"id":"DOC26-I03","area":"I","section":"Data Ingestion and Loading","topic":"COPY INTO · VALIDATE","level":3,"question":"Before writing incoming files into an existing Delta table, an engineer needs to detect parse and target-constraint errors without inserting rows. Which clause is appropriate?","options":["OVERWRITE","FORCE","PATTERN","VALIDATE ALL"],"correct":3,"why":"VALIDATE ALL valida los datos que se cargarían sin efectuar la inserción.","whyWrong":"PATTERN filtra nombres; FORCE altera idempotencia; OVERWRITE no es la cláusula de validación.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into","sourceKey":"copy","code":""},{"id":"DOC26-I04","area":"I","section":"Data Ingestion and Loading","topic":"COPY INTO · idempotencia","level":3,"question":"A scheduled COPY INTO runs twice over the same path with identical files and default options. What happens on the second successful run?","options":["The target table is replaced","The command errors because input files already exist","Files previously loaded are skipped","All rows are appended again"],"correct":2,"why":"COPY INTO es reintentable e idempotente por defecto y omite archivos ya cargados.","whyWrong":"No duplica por defecto, no reemplaza el destino y no falla por repetición de archivos.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into","sourceKey":"copy","code":""},{"id":"DOC26-I05","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · schema hints","level":3,"question":"An Auto Loader JSON stream must infer new columns but should treat customer_id as LONG. The team wants addNewColumns to continue working. Which technique is suitable?","options":["Use COPY_OPTIONS (mergeSchema=true) on the stream","Set cloudFiles.schemaHints to customer_id LONG","Specify a complete schema with .schema() and addNewColumns","Set schemaEvolutionMode to none"],"correct":1,"why":"schemaHints orienta el tipo de una columna sin desactivar el esquema inferido con addNewColumns.","whyWrong":"Con esquema completo, addNewColumns no está permitido; las otras opciones no satisfacen evolución y tipo.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":".option('cloudFiles.schemaHints', 'customer_id LONG')"},{"id":"DOC26-I06","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · modo predeterminado","level":3,"question":"An Auto Loader JSON reader specifies a complete StructType schema and no schema evolution mode. A new JSON field appears. What is the default behavior?","options":["The field is written into a new Delta table","The stream always fails and updates schemaLocation","The field is ignored unless explicit rescued-data handling is configured","The stream automatically appends the new field"],"correct":2,"why":"Con esquema declarado, el modo predeterminado es none: columnas nuevas ignoradas salvo rescuedDataColumn.","whyWrong":"addNewColumns es el predeterminado solo cuando no se aporta un esquema completo.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":""},{"id":"DOC26-I07","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · addNewColumns","level":3,"question":"A JSON Auto Loader stream without an explicit schema sees a new top-level field. Under default evolution, the stream raises UnknownFieldException. What is the intended recovery?","options":["Configure failOnNewColumns and restart unchanged","Delete the existing target and checkpoint","Restart after the schema metadata has been updated","Switch from streaming to a SQL view"],"correct":2,"why":"Auto Loader escribe el nuevo esquema y se detiene; tras reiniciar procesa con la columna añadida.","whyWrong":"No hace falta borrar checkpoints ni cambiar a un modo que impide evolucionar.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":""},{"id":"DOC26-I08","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · rescue","level":3,"question":"A JSON producer introduces unexpected fields frequently. The team wants to retain them for later inspection but not change the declared schema or stop on each new field. Which mode best fits?","options":["failOnNewColumns","addNewColumnsWithTypeWidening","addNewColumns","rescue"],"correct":3,"why":"rescue retiene información desconocida en _rescued_data sin evolucionar el esquema por nuevas columnas.","whyWrong":"addNewColumns puede parar y evolucionar; failOnNewColumns falla; widening está orientado a tipos compatibles.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":""},{"id":"DOC26-I09","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · failOnNewColumns","level":3,"question":"A stream uses schemaEvolutionMode=failOnNewColumns. A previously unseen column arrives. Which statement is true?","options":["The stream silently stores the new field in the primary table schema","The stream automatically overwrites historical records","The stream fails and does not automatically add the new column to its schema","The stream never needs a schema update to resume"],"correct":2,"why":"failOnNewColumns provoca fallo y requiere actualizar el esquema o retirar el archivo conflictivo.","whyWrong":"Es distinto de addNewColumns, que sí actualiza los metadatos antes del reinicio.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":""},{"id":"DOC26-I10","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · descubrimiento","level":3,"question":"Millions of files arrive every day and scanning directories repeatedly is inefficient. What is the recommended scalable file discovery approach when available?","options":["Rescan all folders from scratch on every run","Rely on alphabetical file ordering","Disable checkpoints to accelerate the stream","Use managed file events/notifications with Auto Loader"],"correct":3,"why":"Los eventos de archivos gestionados reducen costes de descubrimiento y escalan mejor.","whyWrong":"No garantizan orden de llegada; el seguimiento incremental sigue necesitando estado.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/file-notification-mode","sourceKey":"fileevents","code":""},{"id":"DOC26-I11","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · estado","level":3,"question":"Which function allows an engineer to inspect the discovery/processing state of individual files tracked by an Auto Loader checkpoint?","options":["TABLE_CHANGES","CLOUD_FILES_STATE","READ_FILES","DESCRIBE HISTORY"],"correct":1,"why":"cloud_files_state consulta el estado de archivos a partir de la ubicación de checkpoint.","whyWrong":"DESCRIBE HISTORY analiza versiones Delta; read_files lee ficheros; table_changes consulta CDF.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/functions/cloud_files_state","sourceKey":"cloudstate","code":"SELECT * FROM cloud_files_state('/Volumes/ops/checkpoints/c1');"},{"id":"DOC26-I12","area":"I","section":"Data Ingestion and Loading","topic":"Auto Loader · tipos","level":3,"question":"Under default schema inference for ordinary JSON files (without inferColumnTypes=true), which data type is assigned to discovered user fields?","options":["VARIANT for every JSON column automatically","STRING","INT for all numeric fields","BOOLEAN whenever values include true/false"],"correct":1,"why":"Auto Loader infiere por defecto campos JSON/CSV/XML como STRING en este contexto; los hints o inferColumnTypes pueden cambiarlo.","whyWrong":"No clasifica automáticamente todos los valores como INT, BOOLEAN o VARIANT en la configuración indicada.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":""},{"id":"DOC26-I13","area":"I","section":"Data Ingestion and Loading","topic":"Lakeflow Connect · modalidad","level":3,"question":"A supported SaaS platform requires credential management and incremental synchronization into Unity Catalog with minimal custom code. Which method best aligns with that requirement?","options":["A hand-built REST poller in a scheduled notebook","A supported managed connector in Lakeflow Connect","A regular SELECT directly from a JSON file","A Spark UDF for API authentication"],"correct":1,"why":"Un conector gestionado compatible automatiza gran parte de autenticación, operación e ingesta.","whyWrong":"El código manual agrega mantenimiento; una UDF o SELECT no proporciona ingesta completa.","doc":"https://docs.databricks.com/aws/en/ingestion/overview","sourceKey":"ingest","code":""},{"id":"DOC26-I14","area":"I","section":"Data Ingestion and Loading","topic":"Lakeflow Connect · ficheros","level":3,"question":"A source is a supported SharePoint file repository. The team wants managed file ingestion with authentication, retries, and destination tables without custom Spark source code. What is the best fit?","options":["JDBC read on the SharePoint URL","The Azure Event Hubs standard connector","A Kafka SQL warehouse","Lakeflow Connect managed file connector"],"correct":3,"why":"Los conectores gestionados de archivos incluyen escenarios SharePoint compatibles.","whyWrong":"Los otros conectores están orientados a bases de datos o buses/eventos, no a ese repositorio.","doc":"https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/file-connectors-overview","sourceKey":"fileconnect","code":""},{"id":"DOC26-I15","area":"I","section":"Data Ingestion and Loading","topic":"Lakeflow Connect · componentes","level":3,"question":"A managed file connector is configured for a supported document repository. Which object stores source authentication details as a governed Unity Catalog securable?","options":["CheckpointLocation","Connection","SQL warehouse query history","Pipeline event log"],"correct":1,"why":"Connection es el objeto de Unity Catalog donde se gestionan las credenciales de origen.","whyWrong":"Un checkpoint o log guarda estado de procesamiento, no las credenciales de conexión.","doc":"https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/file-connectors-overview","sourceKey":"fileconnect","code":""},{"id":"DOC26-I16","area":"I","section":"Data Ingestion and Loading","topic":"Lakeflow Connect · CDC","level":3,"question":"In a standard gateway-based database CDC connector, the source must be captured continuously while target ingestion pipelines run periodically. Which statement describes the architecture?","options":["Auto Loader is required to connect directly to the DB log","There can be no intermediate staging location","The gateway captures changes into staging; scheduled pipelines apply them to target tables","Every BI query must trigger an entire source snapshot"],"correct":2,"why":"Un ingestion gateway y staging separan captura continua y procesamiento posterior en destino.","whyWrong":"Las otras opciones niegan o confunden esos componentes gestionados.","doc":"https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/cdc-overview","sourceKey":"lakeflow","code":""},{"id":"DOC26-I17","area":"I","section":"Data Ingestion and Loading","topic":"COPY INTO · FILTROS","level":3,"question":"A source directory contains many file types, but only files matching sales_*.csv should be ingested by COPY INTO. Which clause filters source file paths?","options":["TIMESTAMP AS OF","VALIDATE","PATTERN","COLUMNS"],"correct":2,"why":"PATTERN limita los archivos candidatos según un patrón glob.","whyWrong":"VALIDATE comprueba datos; COLUMNS mapea columnas; TIMESTAMP AS OF se usa en versionado.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into","sourceKey":"copy","code":"COPY INTO bronze.sales\nFROM '/Volumes/raw/landing/'\nFILEFORMAT = CSV\nPATTERN = 'sales_*.csv';"},{"id":"DOC26-I18","area":"I","section":"Data Ingestion and Loading","topic":"Ingesta · selección","level":3,"question":"A source generates JSON files every few minutes into cloud storage. The pipeline should pick up new files incrementally with checkpoints and schema evolution. What is the most natural first choice?","options":["A SQL warehouse on top of a Python list","Manual full directory overwrite","Auto Loader on cloudFiles","A JDBC connector against object storage"],"correct":2,"why":"Auto Loader está diseñado para detectar e ingerir archivos nuevos de manera incremental.","whyWrong":"Los otros métodos no ofrecen el patrón solicitado con descubrimiento incremental y checkpoints.","doc":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceKey":"autoloader","code":""},{"id":"DOC26-I19","area":"I","section":"Data Ingestion and Loading","topic":"Ingesta · cliente REST","level":3,"question":"An internal REST API has no compatible managed connector and requires a custom OAuth flow and payload transformation. What is a reasonable ingestion pattern?","options":["COPY INTO FROM an HTTP JSON response directly","Use Unity Catalog row filters to fetch records","A custom notebook/SDK REST client orchestrated by Lakeflow Jobs, writing governed tables","Force AUTO CDC to call arbitrary APIs without an adapter"],"correct":2,"why":"Un cliente REST propio en notebooks, orquestado con Jobs, cubre APIs no soportadas por conectores.","whyWrong":"COPY INTO lee ubicaciones de archivos; AUTO CDC aplica cambios ya disponibles; los filtros no extraen APIs.","doc":"https://docs.databricks.com/aws/en/ingestion/overview","sourceKey":"detail","code":""},{"id":"DOC26-I20","area":"I","section":"Data Ingestion and Loading","topic":"Ingesta · JDBC","level":3,"question":"A data engineer must extract rows from an external RDBMS not covered by managed connectors, transform them, and land them in Delta. Which API is suitable for source extraction?","options":["spark.read.format(\"jdbc\") with URL and credentials","spark.read.format(\"cloudFiles\") for a database socket","MERGE INTO with a JDBC URL as target table","COPY INTO FROM JDBC as a native SQL source clause"],"correct":0,"why":"Spark JDBC permite leer de un RDBMS externo con opciones de conexión.","whyWrong":"Auto Loader y COPY INTO leen archivos; MERGE opera sobre tablas, no abre por sí mismo un origen JDBC.","doc":"https://docs.databricks.com/aws/en/connect/","sourceKey":"detail","code":"df = spark.read.format('jdbc').option('url', jdbc_url).option('dbtable', 'dbo.orders').load()"},{"id":"DOC26-T01","area":"T","section":"Data Transformation and Modeling","topic":"Joins · anti","level":3,"question":"An engineer wants customer records that have no matching row in an orders DataFrame. Which PySpark join type directly returns these unmatched left-side records?","options":["cross","left_anti","left_semi","left_outer"],"correct":1,"why":"left_anti devuelve únicamente filas del lado izquierdo sin coincidencia.","whyWrong":"left_semi devuelve coincidentes, left_outer conserva todas con nulls, cross realiza producto cartesiano.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":""},{"id":"DOC26-T02","area":"T","section":"Data Transformation and Modeling","topic":"Joins · semi","level":3,"question":"A team needs the distinct set of orders that have a matching payment record, but none of the payment columns should appear in the result. Which join type is most direct?","options":["full_outer","left_semi","left_anti","cross"],"correct":1,"why":"left_semi conserva solo las filas izquierdas que tienen coincidencia, sin columnas derechas.","whyWrong":"full_outer y cross incluyen otras combinaciones; left_anti hace exactamente lo contrario.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":""},{"id":"DOC26-T03","area":"T","section":"Data Transformation and Modeling","topic":"Joins · broadcast","level":3,"question":"A 200 GB events DataFrame is joined to an 8 MB lookup dimension on product_id. Which PySpark construct explicitly suggests broadcasting the dimension?","options":["events.crossJoin(dim)","dim.collect() followed by Python dictionary filtering","events.repartition(1).join(dim)","events.join(broadcast(dim), \"product_id\")"],"correct":3,"why":"broadcast(dim) marca la dimensión pequeña como candidata a broadcast join.","whyWrong":"repartition(1) suele empeorar paralelismo; crossJoin produce producto cartesiano; collect sobre driver no es el join adecuado.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":"from pyspark.sql.functions import broadcast\nresult = events.join(broadcast(dim), 'product_id')"},{"id":"DOC26-T04","area":"T","section":"Data Transformation and Modeling","topic":"Union · orden","level":3,"question":"Two DataFrames have identical column names but different column positions. They must append rows aligning fields by name. Which operation should be used?","options":["df1.intersect(df2)","df1.join(df2)","df1.union(df2)","df1.unionByName(df2)"],"correct":3,"why":"unionByName empareja columnas por nombre antes de apilar filas.","whyWrong":"union usa posición, join combina columnas y intersect devuelve valores comunes.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":""},{"id":"DOC26-T05","area":"T","section":"Data Transformation and Modeling","topic":"Union · duplicados","level":3,"question":"An engineer performs df1.union(df2) in PySpark and must eliminate duplicate resulting rows. Which statement is correct?","options":["unionByName also always removes duplicate rows","union appends rows by position; distinct() can remove duplicate rows afterward","union removes duplicates automatically, as SQL UNION","A join must replace union because no deduplication is possible"],"correct":1,"why":"DataFrame.union tiene comportamiento tipo UNION ALL; distinct() elimina duplicados si hace falta.","whyWrong":"En PySpark ni union ni unionByName deduplican automáticamente.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":""},{"id":"DOC26-T06","area":"T","section":"Data Transformation and Modeling","topic":"Arrays · explode","level":3,"question":"A column items contains [\"A\",\"B\"] and another contains [\"C\"]. The target requires one row per array item with the other row columns retained. Which expression does this?","options":["array_distinct(items)","concat(items)","collect_list(items)","explode(items)"],"correct":3,"why":"explode convierte cada elemento de un array en una fila separada.","whyWrong":"array_distinct trata duplicados internos; concat concatena; collect_list crea listas agregadas.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/functions","sourceKey":"functions","code":""},{"id":"DOC26-T07","area":"T","section":"Data Transformation and Modeling","topic":"Texto · split","level":3,"question":"A source column region_codes contains a pipe-separated STRING such as \"ES|PT|FR\". Which PySpark function returns an array of individual codes?","options":["countDistinct(col(\"region_codes\"))","explode(col(\"region_codes\"))","unionByName(col(\"region_codes\"))","split(col(\"region_codes\"), \"\\|\")"],"correct":3,"why":"split con expresión regular escapada para | produce un array de tokens.","whyWrong":"explode espera un array/map; countDistinct agrega y unionByName combina DataFrames.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/functions","sourceKey":"functions","code":""},{"id":"DOC26-T08","area":"T","section":"Data Transformation and Modeling","topic":"Datos erróneos · TRY_CAST","level":3,"question":"What does SELECT try_cast(\"not_a_number\" AS INT) return when the source and target types support TRY_CAST?","options":["A parsing exception","0","NULL","The string unchanged"],"correct":2,"why":"TRY_CAST devuelve NULL al fallar la conversión de valor si el par de tipos es compatible.","whyWrong":"CAST normal puede fallar; TRY_CAST no devuelve cero ni preserva el texto.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/functions/try_cast","sourceKey":"detail","code":""},{"id":"DOC26-T09","area":"T","section":"Data Transformation and Modeling","topic":"Agregación · facturas únicas","level":3,"question":"Each invoice can have multiple line items. A Gold daily_revenue table needs sum(amount) and number of distinct invoice_ids per date. Which pair of aggregations is correct?","options":["sum(amount) and countDistinct(invoice_id)","sum(invoice_id) and count(amount)","count(amount) and approx_count_distinct(customer_id)","avg(amount) and count(customer_id)"],"correct":0,"why":"sum(amount) agrega importe; countDistinct(invoice_id) cuenta facturas únicas por fecha.","whyWrong":"Contar líneas o clientes no equivale a contar facturas, ni sumar IDs calcula el número de facturas.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/functions","sourceKey":"detail","code":"df.groupBy('invoice_date').agg(\n  F.sum('amount').alias('total'),\n  F.countDistinct('invoice_id').alias('invoices')\n)"},{"id":"DOC26-T10","area":"T","section":"Data Transformation and Modeling","topic":"Nulos · limpieza","level":3,"question":"A Silver ingestion should remove rows where order_id is NULL while preserving rows whose optional description is NULL. Which filter is most appropriate?","options":["df.distinct()","df.fillna({\"order_id\": 0})","df.filter(F.col(\"order_id\").isNotNull())","df.na.drop() with no subset"],"correct":2,"why":"Filtrar order_id no nulo descarta solo las filas sin clave obligatoria.","whyWrong":"na.drop sin subset puede eliminar por description; fillna falsifica claves; distinct solo quita duplicados.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":""},{"id":"DOC26-T11","area":"T","section":"Data Transformation and Modeling","topic":"DataFrame · deduplicación","level":3,"question":"A dataset is duplicated according to business keys (order_id, line_number), but different loads may contain different ingestion timestamps. Which operation directly removes duplicates based on those keys?","options":["distinct([\"order_id\", \"line_number\"])","groupBy().collect()","dropDuplicates([\"order_id\", \"line_number\"])","drop(\"ingestion_timestamp\")"],"correct":2,"why":"dropDuplicates(subset) permite deduplicar usando las columnas de clave señaladas.","whyWrong":"distinct actúa sobre filas completas y no recibe ese subset de esa forma; borrar columnas no decide qué registro conservar.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"pyspark","code":""},{"id":"DOC26-T12","area":"T","section":"Data Transformation and Modeling","topic":"Silver · normalización","level":3,"question":"Bronze stores amounts as strings, sometimes malformed. Silver must parse valid numerics but keep malformed rows for a separate quality review. Which expression avoids aborting on invalid numeric text?","options":["TRY_CAST(amount AS DOUBLE)","COUNT(DISTINCT amount)","CAST(amount AS DOUBLE) in every configuration","DELETE every row where amount is STRING"],"correct":0,"why":"TRY_CAST permite obtener NULL para conversiones inválidas sin tirar toda la transformación.","whyWrong":"La conversión directa puede fallar; DELETE pierde trazabilidad y count no realiza parsing.","doc":"https://docs.databricks.com/aws/en/sql/language-manual/functions/try_cast","sourceKey":"detail","code":""},{"id":"DOC26-T13","area":"T","section":"Data Transformation and Modeling","topic":"Streaming vs MV","level":3,"question":"Gold joins current customer attributes with sales aggregations; corrections to historical customer rows must be reflected on refresh. Which object best fits by default?","options":["An append-only streaming table ignoring old updates","A materialized view","A CSV file written once","A temporary SQL view persisted as Delta without materialization"],"correct":1,"why":"Una materialized view puede reflejar cambios de las fuentes en refrescos; el motor decide incrementalidad o recomputación.","whyWrong":"Streaming append-only no reevalúa cambios históricos sin estrategia adicional.","doc":"https://docs.databricks.com/aws/en/ldp/concepts","sourceKey":"ldp","code":""},{"id":"DOC26-T14","area":"T","section":"Data Transformation and Modeling","topic":"Materialized view · refresco","level":3,"question":"A pipeline materialized view has a complex query that is not eligible for incremental refresh. What can Databricks do to maintain its result?","options":["It can perform a full recomputation on refresh","It permanently disables the materialized view","It silently omits all modified rows","It must turn automatically into an append-only streaming table"],"correct":0,"why":"Una materialized view puede recomputarse completamente si no es posible mantenerla incrementalmente.","whyWrong":"Refresco incremental es una optimización condicional, no una garantía universal.","doc":"https://docs.databricks.com/aws/en/ldp/concepts","sourceKey":"ldp","code":""},{"id":"DOC26-T15","area":"T","section":"Data Transformation and Modeling","topic":"Spark Declarative Pipelines · anotación","level":3,"question":"In Python Lakeflow Spark Declarative Pipelines, which decorator declares a materialized view?","options":["@dp.stream","@dp.managed_delta","@dp.table","@dp.materialized_view"],"correct":3,"why":"@dp.materialized_view declara expresamente una vista materializada en la API actual.","whyWrong":"@dp.table está dirigido a tablas streaming; las otras formas no son el decorador correspondiente.","doc":"https://docs.databricks.com/aws/en/ldp/developer/sql-vs-python","sourceKey":"sqlpython","code":"from pyspark import pipelines as dp\n\n@dp.materialized_view\ndef sales_gold():\n    return spark.read.table('sales_silver')"},{"id":"DOC26-T16","area":"T","section":"Data Transformation and Modeling","topic":"Expectations · acción","level":3,"question":"A pipeline must stop the affected flow if amount <= 0, rather than drop rows and continue. Which expectation API expresses this?","options":["dp.expect_or_drop(\"valid\", \"amount > 0\")","dp.ignore_invalid(\"valid\")","dp.expect_or_fail(\"valid\", \"amount > 0\")","dp.expect(\"valid\", \"amount > 0\")"],"correct":2,"why":"expect_or_fail obliga a fallar la actualización del flujo afectado al incumplir la regla.","whyWrong":"expect registra, expect_or_drop descarta filas y continue, ignore_invalid no es esta API.","doc":"https://docs.databricks.com/aws/en/ldp/expectations","sourceKey":"expect","code":""},{"id":"DOC26-T17","area":"T","section":"Data Transformation and Modeling","topic":"Expectations · métricas","level":3,"question":"A streaming transformation should record how many records violate a rule but keep those records for later investigation. Which expectation behavior is appropriate?","options":["VACUUM invalid records","WARN / @dp.expect","FAIL UPDATE / @dp.expect_or_fail","DROP ROW / @dp.expect_or_drop"],"correct":1,"why":"WARN mantiene filas y registra métricas de calidad.","whyWrong":"DROP pierde las filas inválidas; FAIL detiene el flujo; VACUUM es mantenimiento físico.","doc":"https://docs.databricks.com/aws/en/ldp/expectations","sourceKey":"expect","code":""},{"id":"DOC26-T18","area":"T","section":"Data Transformation and Modeling","topic":"AUTO CDC · SCD2","level":3,"question":"Out-of-order customer CDC events must produce complete history with validity intervals. Which AUTO CDC configuration is necessary?","options":["APPEND all rows and use DISTINCT","SEQUENCE BY current_timestamp(), STORED AS SCD TYPE 1","GROUP BY customer_id, MAX(event_time), no CDC flow","KEYS(customer_id), SEQUENCE BY event_time, STORED AS SCD TYPE 2"],"correct":3,"why":"SCD TYPE 2 con claves y SEQUENCE BY conserva versiones __START_AT/__END_AT y gestiona orden de eventos.","whyWrong":"SCD1 sobrescribe; usar llegada actual no representa orden lógico; append sin CDC no conserva intervalos correctamente.","doc":"https://docs.databricks.com/aws/en/ldp/developer/ldp-sql-ref-apply-changes-into","sourceKey":"cdcsql","code":"CREATE FLOW cdc AS AUTO CDC INTO customers_hist\nFROM stream(bronze.customers_cdc)\nKEYS (customer_id)\nSEQUENCE BY change_seq\nSTORED AS SCD TYPE 2;"},{"id":"DOC26-T19","area":"T","section":"Data Transformation and Modeling","topic":"AUTO CDC · desempate","level":3,"question":"Several CDC events share the same timestamp. The source also has a strictly ordered event_id to break ties. How should an AUTO CDC sequence be expressed?","options":["SEQUENCE BY CONCAT(event_time, event_id) interpreted arbitrarily","SEQUENCE BY STRUCT(event_time, event_id)","SEQUENCE BY user_name","SEQUENCE BY RAND()"],"correct":1,"why":"SEQUENCE BY STRUCT ordena primero por timestamp y usa event_id como desempate.","whyWrong":"Concatenaciones arbitrarias y RAND no respetan necesariamente el orden determinista de origen.","doc":"https://docs.databricks.com/aws/en/ldp/cdc","sourceKey":"cdc","code":"SEQUENCE BY STRUCT(event_time, event_id)"},{"id":"DOC26-T20","area":"T","section":"Data Transformation and Modeling","topic":"AUTO CDC · cambios parciales","level":3,"question":"Incoming CDC updates contain NULL for attributes not changed. The team wants to retain the existing values rather than overwrite them with NULL. Which AUTO CDC clause addresses this?","options":["APPLY AS TRUNCATE WHEN","IGNORE NULL UPDATES","DELETE FROM on every update","STORED AS SCD TYPE 2 only"],"correct":1,"why":"IGNORE NULL UPDATES preserva los valores actuales en actualizaciones parciales con nulos representando campos omitidos.","whyWrong":"TRUNCATE y DELETE borran datos; SCD2 por sí solo no establece ese tratamiento de NULL.","doc":"https://docs.databricks.com/aws/en/ldp/developer/ldp-sql-ref-apply-changes-into","sourceKey":"cdcsql","code":""},{"id":"DOC26-J01","area":"J","section":"Working with Lakeflow Jobs","topic":"DAG · dependencias","level":3,"question":"In a job, tasks ingest_A and ingest_B may run in parallel. build_gold must start only when both have succeeded. How should build_gold be configured?","options":["Use At least one succeeded with a dependency on ingest_A only","Depend only on ingest_A","Depend on ingest_A and ingest_B with All succeeded","Set the three tasks to execute at the same time"],"correct":2,"why":"Configurar ambas dependencias con All succeeded obliga a esperar el éxito de las dos.","whyWrong":"Las otras configuraciones no aseguran la finalización satisfactoria de ambas fuentes.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-J02","area":"J","section":"Working with Lakeflow Jobs","topic":"Run if · condición","level":3,"question":"A cleanup task must run after upstream tasks finish regardless of whether they succeeded or failed (assuming their states allow the condition). Which Run if choice is intended?","options":["All done","None failed","At least one succeeded","All succeeded"],"correct":0,"why":"All done evalúa el fin de las dependencias en lugar de exigir éxito.","whyWrong":"All succeeded y None failed imponen condiciones de éxito/ausencia de fallo.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-J03","area":"J","section":"Working with Lakeflow Jobs","topic":"If/else","level":3,"question":"An upstream task emits a row_count task value. Gold processing should run only when row_count > 0. Which Lakeflow task supports this branch?","options":["Run Job task","For each task","If/else condition task","SQL warehouse refresh interval"],"correct":2,"why":"If/else permite bifurcar el DAG mediante una expresión booleana sobre valores.","whyWrong":"For each itera elementos; Run Job invoca otro trabajo.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-J04","area":"J","section":"Working with Lakeflow Jobs","topic":"For each","level":3,"question":"A parameterized notebook must execute once for each region in a dynamically computed array [\"ES\",\"PT\",\"FR\"]. Which control-flow task is designed for this?","options":["For each","If/else","File arrival trigger","Run Job"],"correct":0,"why":"For each itera una tarea anidada por elemento de un array.","whyWrong":"If/else solo bifurca, Run Job llama otro job y el trigger inicia ejecuciones.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-J05","area":"J","section":"Working with Lakeflow Jobs","topic":"Run Job","level":3,"question":"A downstream team has an independently managed Lakeflow Job that must be invoked as one step of a larger orchestration. Which task type should the parent job add?","options":["For each with no child task","Dashboard refresh task","Run Job task","Notebook task with copied source"],"correct":2,"why":"Run Job permite desencadenar otro trabajo desde el DAG sin duplicarlo.","whyWrong":"Copiar código elimina aislamiento/gestión independiente; las otras opciones tienen propósitos distintos.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-J06","area":"J","section":"Working with Lakeflow Jobs","topic":"Reparación","level":3,"question":"Task A succeeded, task B failed, and downstream task C was skipped. Which feature recovers the failed run while avoiding unnecessary reruns of A?","options":["Delete all run history","Full re-deploy of the workspace","Drop and recreate Unity Catalog tables","Repair run"],"correct":3,"why":"Repair run permite reejecutar tareas fallidas/omitidas y dependientes.","whyWrong":"No requiere borrar trabajo ni tablas; un redeploy no equivale a reparar ejecuciones.","doc":"https://docs.databricks.com/aws/en/jobs/repair-job-failures","sourceKey":"detail","code":""},{"id":"DOC26-J07","area":"J","section":"Working with Lakeflow Jobs","topic":"Trigger · actualizaciones","level":3,"question":"Gold should run when a specific supported Unity Catalog source table is updated, without polling on a fixed schedule. Which trigger matches this requirement?","options":["Manual Run now","Table update trigger","Scheduled trigger","File arrival trigger"],"correct":1,"why":"Table update inicia trabajos en función de actualizaciones de tablas vigiladas.","whyWrong":"Scheduled es temporal; file arrival detecta archivos; Run now no es automático.","doc":"https://docs.databricks.com/aws/en/jobs/triggers","sourceKey":"triggers","code":""},{"id":"DOC26-J08","area":"J","section":"Working with Lakeflow Jobs","topic":"Trigger · archivos","level":3,"question":"A pipeline should start when files arrive in a monitored Unity Catalog storage location rather than at a particular time. Which trigger type is intended?","options":["File arrival","Scheduled","Continuous","Table update"],"correct":0,"why":"File arrival responde a la aparición de archivos en una ubicación compatible.","whyWrong":"Table update responde a modificaciones de tablas, continuous encadena runs y scheduled depende del reloj.","doc":"https://docs.databricks.com/aws/en/jobs/triggers","sourceKey":"triggers","code":""},{"id":"DOC26-J09","area":"J","section":"Working with Lakeflow Jobs","topic":"Trigger · continuous","level":3,"question":"A team sets a Lakeflow Job to Continuous. Which description best matches how that job is scheduled?","options":["It executes all tasks as a single continuous Spark task without new runs","It runs only at an exact 5-minute cron schedule","It starts only when a table update event arrives","It launches a new run after the preceding run finishes or fails"],"correct":3,"why":"Continuous inicia ejecuciones consecutivas tras finalizar o fallar la ejecución precedente.","whyWrong":"No es sinónimo de un cron ni de un trigger de archivos/tablas.","doc":"https://docs.databricks.com/aws/en/jobs/triggers","sourceKey":"triggers","code":""},{"id":"DOC26-J10","area":"J","section":"Working with Lakeflow Jobs","topic":"Concurrencia","level":3,"question":"A scheduled job sometimes overlaps its previous execution. By default, what prevents simultaneous runs from exceeding the job concurrency limit?","options":["The SQL warehouse automatically creates more independent jobs","Each job allows infinite concurrent runs by default","The configured maximum concurrent runs; excess triggers can be skipped","A row filter stops all schedule executions"],"correct":2,"why":"El límite max concurrent runs controla ejecuciones activas, por defecto una.","whyWrong":"No hay concurrencia ilimitada por defecto y la seguridad no es un regulador de runs.","doc":"https://docs.databricks.com/aws/en/jobs/triggers","sourceKey":"triggers","code":""},{"id":"DOC26-J11","area":"J","section":"Working with Lakeflow Jobs","topic":"Cómputo de tareas","level":3,"question":"A Lakeflow Job consists of a SQL query task and a Python notebook task. Which allocation is generally appropriate?","options":["Both tasks must always use a single Spark Submit JAR","SQL query on SQL warehouse; notebook on serverless jobs compute if supported","SQL query on Photon disabled all-purpose; notebook on dashboard compute","Both tasks must use the same SQL warehouse"],"correct":1,"why":"Las tareas usan cómputo según tipo: warehouse para SQL y serverless jobs para notebooks compatibles.","whyWrong":"No obliga a compartir cómputo ni a usar un cluster sin soporte específico.","doc":"https://docs.databricks.com/aws/en/jobs/compute","sourceKey":"jobscompute","code":""},{"id":"DOC26-J12","area":"J","section":"Working with Lakeflow Jobs","topic":"Dependencias · error","level":3,"question":"A task with the default Run if condition depends on two upstream tasks; one fails. What should happen to the downstream task?","options":["It becomes eligible immediately","It is not run, typically marked upstream failed","It runs because one predecessor succeeded","It converts to a continuous trigger"],"correct":1,"why":"All succeeded por defecto exige que todas las dependencias terminen correctamente.","whyWrong":"Un predecesor correcto no basta con la condición predeterminada.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-J13","area":"J","section":"Working with Lakeflow Jobs","topic":"Reintentos","level":3,"question":"An API occasionally returns a transient 503 causing one notebook task to fail. Which Lakeflow Job setting is intended to retry that task automatically?","options":["max_retries / retry configuration for that task","Disable job run history","Replace the notebook task with a dashboard task","Set the target table to external"],"correct":0,"why":"Configurar reintentos de la tarea permite tolerar fallos transitorios.","whyWrong":"Tipo de tabla, dashboard e historial no son mecanismos de retry.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/job-task-types","sourceKey":"detail","code":""},{"id":"DOC26-J14","area":"J","section":"Working with Lakeflow Jobs","topic":"Run if · alternativa","level":3,"question":"A downstream task may proceed if EITHER of two upstream independent validation tasks succeeds. Which Run if condition captures this?","options":["All done","At least one succeeded","All succeeded","At least one failed"],"correct":1,"why":"At least one succeeded admite que una dependencia falle mientras otra tiene éxito.","whyWrong":"All succeeded exige ambas; All done no exige éxitos; At least one failed comprueba fallos.","doc":"https://docs.databricks.com/aws/en/jobs/run-if","sourceKey":"jobs","code":""},{"id":"DOC26-C01","area":"C","section":"Implementing CI/CD","topic":"Bundles · targets","level":3,"question":"A project contains targets dev and prod. Which CLI command deploys the bundle resources to the prod target?","options":["databricks bundle run prod","databricks bundle validate -t prod","databricks bundle deploy -t prod","databricks workspace import prod"],"correct":2,"why":"bundle deploy -t prod publica recursos del bundle sobre el target prod.","whyWrong":"validate solo valida; run ejecuta un recurso y workspace import no despliega el bundle.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/reference","sourceKey":"bundle","code":""},{"id":"DOC26-C02","area":"C","section":"Implementing CI/CD","topic":"Bundles · validación","level":3,"question":"Before deploying changes, a CI pipeline must check the bundle configuration for errors without creating workspace resources. Which command is appropriate?","options":["databricks bundle deploy -t prod","databricks bundle destroy -t prod","databricks bundle validate -t prod","databricks bundle run -t prod etl"],"correct":2,"why":"bundle validate verifica configuración y sustituciones sin desplegar activos.","whyWrong":"deploy cambia recursos, run los ejecuta y destroy los elimina.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/reference","sourceKey":"bundle","code":""},{"id":"DOC26-C03","area":"C","section":"Implementing CI/CD","topic":"Bundles · modo dev","level":3,"question":"A target specifies mode: development. With default behavior and no overrides, what happens to schedules/triggers on deployed jobs?","options":["They are paused by default","They are forcibly deleted","They are automatically scheduled every minute","They are always enabled in all development workspaces"],"correct":0,"why":"Development mode pausa schedules/triggers por defecto para prevenir ejecuciones involuntarias.","whyWrong":"No implica borrado ni activación obligatoria; los presets permiten excepciones.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes","sourceKey":"bundlemode","code":"targets:\n  dev:\n    mode: development"},{"id":"DOC26-C04","area":"C","section":"Implementing CI/CD","topic":"Bundles · variables","level":3,"question":"The same bundle must deploy to dev and prod, with different catalog names and service endpoints but the same code. Which design is best?","options":["Hardcode catalog=prod everywhere in notebooks","Use target-specific variables/overrides in the bundle configuration","Copy the project into two unrelated repositories","Rename all resources manually after deploying"],"correct":1,"why":"Los targets y variables permiten parametrizar valores específicos por entorno sin duplicar la base de código.","whyWrong":"Duplicar o codificar valores en el código perjudica trazabilidad y consistencia del despliegue.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/reference","sourceKey":"bundle","code":""},{"id":"DOC26-C05","area":"C","section":"Implementing CI/CD","topic":"Bundles · recursos","level":3,"question":"Which top-level bundle resource mapping is appropriate for declaring a Lakeflow Job managed by a Declarative Automation Bundle?","options":["cloudFiles.schemaLocation","resources.jobs","resources.sql.only","workspace.git.pull_request"],"correct":1,"why":"Los trabajos se declaran bajo resources.jobs en el YAML del bundle.","whyWrong":"Las otras claves no son el mapeo de recursos para Jobs.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/reference","sourceKey":"bundle","code":"resources:\n  jobs:\n    sales_etl:\n      name: sales-etl"},{"id":"DOC26-C06","area":"C","section":"Implementing CI/CD","topic":"Bundles · prod","level":3,"question":"A target uses mode: production and specifies git.branch: main. A deployment runs from feature/change with no force override. What behavior should you expect?","options":["Production mode ignores the branch constraint","The bundle automatically switches to dev mode","The CLI silently merges feature/change into main","The deployment is validated against the configured branch and can be rejected"],"correct":3,"why":"Production mode comprueba coincidencia de rama si se especifica git.branch; puede rechazar despliegues desde otra rama.","whyWrong":"El CLI no hace merges por sí mismo ni ignora esa validación por defecto.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes","sourceKey":"bundlemode","code":""},{"id":"DOC26-C07","area":"C","section":"Implementing CI/CD","topic":"Git folders · revisión","level":3,"question":"A team uses Databricks Git folders and an external Git provider. Where is a pull request generally reviewed and merged?","options":["In the external Git provider (for example GitHub)","Only inside a Databricks SQL warehouse","In a Delta table history log","In the Unity Catalog privilege editor"],"correct":0,"why":"Los PR se revisan y fusionan en el proveedor Git; la carpeta de Databricks sincroniza/edita versiones de archivos.","whyWrong":"No es una acción de SQL warehouse, Delta log o controles Unity Catalog.","doc":"https://docs.databricks.com/aws/en/repos/ci-cd","sourceKey":"detail","code":""},{"id":"DOC26-C08","area":"C","section":"Implementing CI/CD","topic":"Git · fetch vs commit","level":3,"question":"An engineer modifies notebook code inside a Git folder, but wants to make the changes available to remote collaborators. Which sequence is most appropriate?","options":["Run COPY INTO to create a Git commit","Change the SQL warehouse name to match the branch","Commit the local changes and push to the remote branch","Pull then delete the local branch"],"correct":2,"why":"Commit registra los cambios localmente y push los publica en la rama remota.","whyWrong":"Pull recupera cambios del remoto; COPY INTO y nombres de warehouse no gestionan versionado.","doc":"https://docs.databricks.com/aws/en/repos/ci-cd","sourceKey":"detail","code":""},{"id":"DOC26-C09","area":"C","section":"Implementing CI/CD","topic":"Bundles · ejecutar","level":3,"question":"A bundle has already been deployed to test. What CLI command executes its etl_job resource against the test target?","options":["databricks bundle deploy -t prod etl_job","databricks bundle validate -t test etl_job","databricks bundle run -t test etl_job","databricks bundle destroy -t test etl_job"],"correct":2,"why":"bundle run -t test etl_job ejecuta el recurso identificado en ese target.","whyWrong":"validate comprueba, destroy elimina y deploy no ejecuta necesariamente el recurso.","doc":"https://docs.databricks.com/aws/en/dev-tools/bundles/reference","sourceKey":"bundle","code":""},{"id":"DOC26-O01","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Spark UI · skew","level":3,"question":"A Spark stage has 150 tasks. The median task runs 5 seconds, but one runs 12 minutes and reads 45 times more shuffle data. Which cause is most likely?","options":["A missing Git branch","Data skew in one or more shuffle partitions","A table name that is too long","An expired dashboard cache"],"correct":1,"why":"Duraciones y volúmenes altamente desiguales entre tareas son síntomas de data skew.","whyWrong":"Git, nombres de tablas y caché de dashboards no explican esa asimetría del stage.","doc":"https://docs.databricks.com/aws/en/optimizations/aqe","sourceKey":"aqe","code":""},{"id":"DOC26-O02","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Spark UI · spill","level":3,"question":"Spark UI shows high disk spill across join and aggregation tasks. What is the most direct interpretation?","options":["The job performed VACUUM on old Delta files","Spark wrote intermediate execution data to disk because it did not fit in available execution memory","The notebook exported final tables to CSV","Unity Catalog revoked SELECT privileges"],"correct":1,"why":"Disk spill es descarga a disco de datos intermedios que no caben en memoria de ejecución.","whyWrong":"No significa eliminación VACUUM, permisos ni exportación final.","doc":"https://docs.databricks.com/aws/en/compute/troubleshooting/debugging-spark-ui","sourceKey":"sparkui","code":""},{"id":"DOC26-O03","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"AQE · reordenar joins","level":3,"question":"A complex SQL statement would benefit from a different join order. An engineer assumes AQE will reorder all joins dynamically. Which statement is accurate?","options":["AQE only applies to Git workflows","AQE always reorders all joins after each stage","AQE does not perform join reordering at runtime; statistics may help the cost-based optimizer","AQE cannot coalesce shuffle partitions"],"correct":2,"why":"AQE ajusta planes físicos como join strategy y particiones, pero no reordena joins en ejecución.","whyWrong":"Las otras opciones confunden capacidades y limitaciones de AQE.","doc":"https://docs.databricks.com/aws/en/optimizations/aqe","sourceKey":"aqe","code":""},{"id":"DOC26-O04","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"AQE · skew","level":3,"question":"A skewed shuffle-based LEFT OUTER JOIN is executed with AQE. Which join side can AQE split for supported skew handling?","options":["Both sides unconditionally for any join type","The left side, subject to the relevant skew conditions","Neither side of any outer join","Only the right (non-preserved) side"],"correct":1,"why":"Databricks documenta soporte de optimización de skew en el lado izquierdo de LEFT OUTER.","whyWrong":"El lado derecho no es equivalente; el tipo de join condiciona qué lado puede optimizarse.","doc":"https://docs.databricks.com/aws/en/optimizations/aqe","sourceKey":"aqe","code":""},{"id":"DOC26-O05","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Databricks Jobs · tendencia","level":3,"question":"A scheduled pipeline historically takes 8 minutes, but the last 10 runs take 30 minutes. Where should an engineer first compare timings and isolate slow tasks?","options":["Git commit message search only","Catalog comments only","The cloud storage billing invoice","Lakeflow Jobs run history and task details"],"correct":3,"why":"Run history permite comparar duraciones y estados; task details localiza fases lentas.","whyWrong":"Las demás fuentes no muestran la secuencia histórica de runs y tiempos por tarea.","doc":"https://docs.databricks.com/aws/en/jobs/monitor","sourceKey":"detail","code":""},{"id":"DOC26-O06","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Delta · archivos pequeños","level":3,"question":"Frequent microbatch writes have created hundreds of thousands of tiny Delta files, slowing scans. Which operation most directly compacts files?","options":["OPTIMIZE","DESCRIBE HISTORY","VACUUM","REVOKE"],"correct":0,"why":"OPTIMIZE compacta y reorganiza archivos Delta activos.","whyWrong":"VACUUM borra archivos obsoletos elegibles, pero no compacta los activos.","doc":"https://docs.databricks.com/aws/en/optimizations","sourceKey":"opt","code":""},{"id":"DOC26-O07","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Liquid Clustering","level":3,"question":"An engineer enables Liquid Clustering on a Delta table to improve common selective queries. What should they avoid configuring together with it?","options":["A Unity Catalog catalog","Delta Lake transaction logging","Photon compute","ZORDER-based layout on the same table"],"correct":3,"why":"Liquid Clustering sustituye el layout de ZORDER/particionado clásico y no se combina con ZORDER en una misma tabla.","whyWrong":"Unity Catalog, Delta y Photon son compatibles en escenarios adecuados.","doc":"https://docs.databricks.com/aws/en/optimizations","sourceKey":"opt","code":""},{"id":"DOC26-O08","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Predictive optimization","level":3,"question":"A team manages Unity Catalog managed tables and wants Databricks to automate appropriate OPTIMIZE, ANALYZE and VACUUM maintenance. Which feature applies?","options":["Predictive optimization","Auto Loader rescue","Databricks Git folders","Serverless SQL query history"],"correct":0,"why":"Predictive optimization automatiza mantenimiento de tablas managed elegibles.","whyWrong":"Rescue es ingesta, query history observabilidad y Git versión de código.","doc":"https://docs.databricks.com/aws/en/optimizations","sourceKey":"opt","code":""},{"id":"DOC26-O09","area":"O","section":"Troubleshooting, Monitoring, and Optimization","topic":"Driver OOM","level":3,"question":"A notebook fails when a developer calls df.collect() on a 100 GB DataFrame. Executor task stages had previously completed. What is the most plausible immediate cause?","options":["Auto Loader duplicated source file history","Driver memory exhaustion from collecting all rows locally","Unity Catalog automatically blocked all aggregations","Liquid Clustering skipped records"],"correct":1,"why":"collect() transfiere todas las filas al driver y puede agotar su memoria.","whyWrong":"No se debe atribuir a clustering, Auto Loader o permisos si el síntoma coincide con la materialización en driver.","doc":"https://docs.databricks.com/aws/en/pyspark/reference/classes/dataframe","sourceKey":"detail","code":""},{"id":"DOC26-S01","area":"S","section":"Governance and Security","topic":"ABAC · MATCH COLUMNS","level":3,"question":"A governed column tag is pii=ssn. A policy must find only columns with that exact key-value pair. Which predicate should follow MATCH COLUMNS?","options":["COMMENT('pii=ssn') AS c","has_tag_value('ssn', 'pii') AS c","has_tag('ssn') AS c","has_tag_value('pii', 'ssn') AS c"],"correct":3,"why":"has_tag_value recibe clave primero y valor después. pii=ssn significa clave pii y valor ssn.","whyWrong":"Invertir parámetros cambia significado; has_tag solo busca clave; COMMENT no aplica políticas.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":"MATCH COLUMNS has_tag_value('pii', 'ssn') AS ssn_col\nON COLUMN ssn_col"},{"id":"DOC26-S02","area":"S","section":"Governance and Security","topic":"ABAC · has_tag","level":3,"question":"A column is tagged pii=email. What is true about MATCH COLUMNS has_tag(\"pii\") AS c?","options":["It masks rows whose values look like emails","It matches only columns with pii=ssn","It matches columns with tag key pii regardless of the value","It is equivalent to a COMMENT on a column"],"correct":2,"why":"has_tag comprueba presencia de la clave, independientemente del valor específico.","whyWrong":"No inspecciona valores almacenados ni representa comentarios SQL.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":""},{"id":"DOC26-S03","area":"S","section":"Governance and Security","topic":"ABAC · herencia","level":3,"question":"A catalog has governed tag pii=ssn, but no column directly has pii. A policy uses MATCH COLUMNS has_tag_value(\"pii\",\"ssn\") AS c. What is the expected matching behavior?","options":["It matches every column via catalog inheritance","It matches all STRING columns","It only matches directly tagged columns, not all descendants via table/catalog tags","It fails because governed tags are not supported by ABAC"],"correct":2,"why":"Las etiquetas de columnas no heredan tags de tablas/catálogos en MATCH COLUMNS; deben establecerse directamente.","whyWrong":"La herencia de tags a tablas en WHEN no implica herencia a columnas.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":""},{"id":"DOC26-S04","area":"S","section":"Governance and Security","topic":"ABAC · ON COLUMN","level":3,"question":"An ABAC mask policy defines MATCH COLUMNS has_tag_value(\"pii\",\"email\") AS e. Which clause identifies the column whose value is passed automatically as the first UDF argument?","options":["GRANT SELECT e","ON COLUMN e","WHEN e","ROW FILTER e"],"correct":1,"why":"ON COLUMN e elige la columna enmascarada y la enlaza al primer parámetro de la UDF.","whyWrong":"WHEN filtra aplicabilidad por tabla; GRANT y ROW FILTER no seleccionan el dato a enmascarar.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":""},{"id":"DOC26-S05","area":"S","section":"Governance and Security","topic":"ABAC · dos columnas","level":3,"question":"A mask_email_by_consent(email STRING, consent BOOLEAN) UDF requires a second column to decide whether to reveal an email. Which policy pattern supplies the second value?","options":["MATCH COLUMNS for email and consent, ON COLUMN email alias, USING COLUMNS(consent alias)","GRANT MODIFY on consent to all users","A single MATCH COLUMNS expression with no USING COLUMNS","Call has_tag_value on individual email string values"],"correct":0,"why":"Para usar otro campo en la UDF se identifica con MATCH COLUMNS y se pasa por USING COLUMNS.","whyWrong":"ON COLUMN ya aporta email como primer argumento, pero no inyecta automáticamente columnas adicionales.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/tutorial-sql","sourceKey":"abacsql","code":"MATCH COLUMNS has_tag_value('pii','email') AS e,\n              has_tag('consent') AS consent_col\nON COLUMN e\nUSING COLUMNS (consent_col)"},{"id":"DOC26-S06","area":"S","section":"Governance and Security","topic":"ABAC · WHERE vs WHEN","level":3,"question":"A policy should apply only to tables classified=restricted, then mask columns tagged pii=ssn. How should the tag predicates be assigned?","options":["MATCH COLUMNS for table tag and WHEN for individual column content","COMMENT both tags; no policy required","WHEN for table tag and MATCH COLUMNS for column tag","WHERE on stored SSN values only"],"correct":2,"why":"WHEN determina aplicabilidad a tablas; MATCH COLUMNS identifica columnas de esas tablas.","whyWrong":"Las otras respuestas invierten niveles o sustituyen políticas por comentarios.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":"WHEN has_tag_value('classification','restricted')\nMATCH COLUMNS has_tag_value('pii','ssn') AS ssn\nON COLUMN ssn"},{"id":"DOC26-S07","area":"S","section":"Governance and Security","topic":"ABAC · nombre heredado","level":3,"question":"An older example uses hasTagValue(\"pii\", \"ssn\"). What is the preferred modern spelling for new policies?","options":["hasTagVal(\"pii\", \"ssn\")","has_tag_value(\"pii\", \"ssn\")","contains_column_value(\"pii\", \"ssn\")","column_tag_is(\"pii\", \"ssn\")"],"correct":1,"why":"La documentación recomienda snake_case has_tag_value, aunque formas antiguas camelCase siguen funcionando.","whyWrong":"Las demás alternativas no son el nombre documentado de esa función.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":""},{"id":"DOC26-S08","area":"S","section":"Governance and Security","topic":"Permisos · consulta","level":3,"question":"An analyst receives SELECT on main.sales.orders but has no privileges on its parent catalog and schema. What additional privileges are normally needed?","options":["WRITE FILES on the warehouse","USE CATALOG on main and USE SCHEMA on main.sales","MANAGE on the metastore","CREATE TABLE on main.sales only"],"correct":1,"why":"Consultar una tabla normalmente requiere SELECT y USAGE del catálogo y esquema ascendentes.","whyWrong":"MANAGE, CREATE TABLE o permiso de escritura no son necesarios para lectura básica.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/permissions-concepts","sourceKey":"perm","code":""},{"id":"DOC26-S09","area":"S","section":"Governance and Security","topic":"Permisos · BROWSE","level":3,"question":"What does granting BROWSE on a Unity Catalog catalog provide?","options":["Ability to discover metadata without automatically gaining SELECT on underlying data","Unrestricted access to table row data","Automatic MODIFY on all objects","The ability to mask every column"],"correct":0,"why":"BROWSE permite descubrir metadatos, no consultar filas sin privilegios de lectura.","whyWrong":"No sustituye SELECT, MODIFY ni políticas ABAC.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/permissions-concepts","sourceKey":"perm","code":""},{"id":"DOC26-S10","area":"S","section":"Governance and Security","topic":"Managed vs external","level":3,"question":"An external Delta table registered in Unity Catalog is dropped. Which behavior is normally expected?","options":["Metadata is removed; underlying files remain","Every file is converted into a managed volume","All cloud data files are immediately erased","The cloud storage account is closed"],"correct":0,"why":"DROP TABLE sobre external elimina metadatos de Unity Catalog pero conserva archivos.","whyWrong":"El ciclo de vida de datos externos permanece bajo control del almacenamiento externo.","doc":"https://docs.databricks.com/aws/en/tables/types","sourceKey":"managed","code":""},{"id":"DOC26-S11","area":"S","section":"Governance and Security","topic":"Managed · recuperación","level":3,"question":"A managed Unity Catalog table is accidentally dropped. During the supported recovery window, which feature is intended to restore it?","options":["UNDROP TABLE","COPY INTO with FORCE","SHOW GRANTS","SET MASK"],"correct":0,"why":"UNDROP TABLE permite recuperar tablas managed eliminadas durante la ventana admitida.","whyWrong":"COPY INTO recarga archivos, SHOW GRANTS consulta permisos y SET MASK protege columnas.","doc":"https://docs.databricks.com/aws/en/tables/types","sourceKey":"managed","code":""},{"id":"DOC26-S12","area":"S","section":"Governance and Security","topic":"Convertir a managed","level":3,"question":"An existing Unity Catalog external Delta table should be converted to a managed table while retaining its identity and associated settings when supported. Which SQL operation is intended?","options":["ALTER TABLE ... SET MASK","RESTORE TABLE TO VERSION AS OF 0","ALTER TABLE ... SET MANAGED","DROP TABLE then CREATE EXTERNAL VOLUME"],"correct":2,"why":"ALTER TABLE ... SET MANAGED convierte una tabla external Delta compatible a managed.","whyWrong":"SET MASK y RESTORE tienen finalidades distintas; recrear objetos no es la conversión directa.","doc":"https://docs.databricks.com/aws/en/tables/convert-to-managed","sourceKey":"tableconvert","code":""},{"id":"DOC26-S13","area":"S","section":"Governance and Security","topic":"RLS vs masking","level":3,"question":"A policy should hide sales rows outside a user region, but still show the same columns for permitted rows. Which control is appropriate?","options":["Liquid Clustering by region","Column mask only","COPY INTO with VALIDATE","ROW FILTER backed by a boolean UDF"],"correct":3,"why":"ROW FILTER decide si cada fila es visible a partir de una condición booleana.","whyWrong":"Column mask transforma valores, pero no restringe por sí solo el conjunto de filas.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":""},{"id":"DOC26-S14","area":"S","section":"Governance and Security","topic":"Políticas · grupos","level":3,"question":"An ABAC policy should apply to all account users except members of compliance_admins. Which clause pattern implements principal targeting and exclusion?","options":["USING COLUMNS (`compliance_admins`)","MATCH COLUMNS session_user() AS principal","TO `account users` EXCEPT `compliance_admins`","WHEN NOT has_tag(\"compliance_admins\")"],"correct":2,"why":"TO/EXCEPT selecciona a qué identidades afecta la política, dejando fuera al grupo exento.","whyWrong":"WHEN y MATCH COLUMNS evalúan recursos, y USING COLUMNS pasa argumentos a UDF.","doc":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/core-concepts","sourceKey":"abac","code":""}];
const DOCUMENTAL_2026_AREAS={"P":"Plataforma","I":"Ingesta","T":"Transformación","J":"Lakeflow Jobs","C":"CI/CD","O":"Optimización","S":"Seguridad"};
function documental2026Questions(){return DOCUMENTAL_2026_RAW.map(x=>({
 id:x.id,topic:"Documentación 2026",category:"Doc 2026 · "+DOCUMENTAL_2026_AREAS[x.area],
 question:x.question+(x.code?"\n\n```\n"+x.code+"\n```":""),
 options:x.options.map((text,i)=>({key:"ABCDE"[i],text})),
 correct:["ABCDE"[x.correct]],explanation:x.why,answerWhy:x.why,
 wrongWhy:{},whyWrongGeneric:x.whyWrong,sourceLinks:[{label:"Databricks Docs · "+x.topic,url:x.doc}],
 scorable:true,issue:null,documental2026:true,docArea:x.area,docTopic:x.topic
}));}
